1	import { useState } from 'react';
2	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
3	import { getJson, postJson } from '../../api/http';
4	
5	// A tag as the server returns it: an id and a name. Tags are reusable labels shared across projects.
6	export type Tag = {
7	  id: number;
8	  name: string;
9	};
10	
11	// A project↔tag pairing, with the tag's name resolved so a chip can render its label directly.
12	export type ProjectTag = {
13	  projectId: number;
14	  tagId: number;
15	  name: string;
16	};
17	
18	// A project's tags, rendered in the project-detail context: the chips already on this project, a
19	// per-chip remove button, and a select of the remaining tags to add one. Both lists come from
20	// useQuery — every tag under ['tags'], every pairing under ['projectTags'] — and are filtered to
21	// this project here (rule 5); nothing is copied into state or hand-maintained. Adding and removing
22	// are useMutations that invalidate ['projectTags'], so the chips refetch themselves. The only
23	// useState is the tag the user has currently picked but not yet added (rule 4).
24	export function ProjectTagsPanel({ projectId }: { projectId: number }) {
25	  const queryClient = useQueryClient();
26	  const tags = useQuery({
27	    queryKey: ['tags'],
28	    queryFn: () => getJson<Tag[]>('/api/tags'),
29	  });
30	  const projectTags = useQuery({
31	    queryKey: ['projectTags'],
32	    queryFn: () => getJson<ProjectTag[]>('/api/project-tags'),
33	  });
34	
